BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $$ BEGIN IF (select jsonb_agg(jsonb_build_array(conrelid::regclass::text,conname,pg_get_constraintdef(oid)) order by conrelid::regclass::text,conname) from pg_constraint where conrelid in ('public.planning_metas_compra'::regclass,'public.rh_custos_mensais'::regclass,'public.rh_escalas'::regclass) or confrelid in ('public.planning_metas_compra'::regclass,'public.rh_custos_mensais'::regclass,'public.rh_escalas'::regclass)) IS DISTINCT FROM $expected$[["planning_metas_compra", "planning_metas_compra_company_fk", "FOREIGN KEY (company_id) REFERENCES companies(id)"], ["planning_metas_compra", "planning_metas_compra_month_check", "CHECK (((month >= 1) AND (month <= 12)))"], ["planning_metas_compra", "planning_metas_compra_pkey", "PRIMARY KEY (id)"], ["planning_metas_compra", "planning_metas_compra_target_value_check", "CHECK ((target_value >= (0)::numeric))"], ["planning_metas_compra", "planning_metas_compra_year_check", "CHECK (((year >= 2020) AND (year <= 2100)))"], ["planning_metas_compra", "planning_metas_compra_year_month_categoria_key", "UNIQUE (year, month, categoria)"], ["rh_custos_mensais", "rh_custos_mensais_company_fk", "FOREIGN KEY (company_id) REFERENCES companies(id)"], ["rh_custos_mensais", "rh_custos_mensais_periodo_key", "UNIQUE (periodo)"], ["rh_custos_mensais", "rh_custos_mensais_pkey", "PRIMARY KEY (id)"], ["rh_escala_slots", "rh_escala_slots_escala_id_fkey", "FOREIGN KEY (escala_id) REFERENCES rh_escalas(id) ON DELETE CASCADE"], ["rh_escalas", "rh_escalas_company_fk", "FOREIGN KEY (company_id) REFERENCES companies(id)"], ["rh_escalas", "rh_escalas_pkey", "PRIMARY KEY (id)"], ["rh_escalas", "rh_escalas_semana_inicio_setor_key", "UNIQUE (semana_inicio, setor)"]]$expected$::jsonb THEN RAISE EXCEPTION 'PHASE7_UPSERT_CONSTRAINTS_DRIFT'; END IF; END $$;
DO $$ BEGIN IF (select jsonb_agg(jsonb_build_array(c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) order by c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where c.relname in ('planning_metas_compra','rh_custos_mensais','rh_escalas') and c.relnamespace='public'::regnamespace and a.attnum>0 and not a.attisdropped) IS DISTINCT FROM $expected$[["planning_metas_compra", "id", "uuid", true, "gen_random_uuid()"], ["planning_metas_compra", "year", "integer", true, null], ["planning_metas_compra", "month", "integer", true, null], ["planning_metas_compra", "categoria", "text", true, null], ["planning_metas_compra", "target_value", "numeric(12,2)", true, null], ["planning_metas_compra", "alerta_amarelo_percent", "numeric(5,2)", true, "85"], ["planning_metas_compra", "alerta_vermelho_percent", "numeric(5,2)", true, "100"], ["planning_metas_compra", "ativo", "boolean", true, "true"], ["planning_metas_compra", "notes", "text", false, null], ["planning_metas_compra", "created_by", "uuid", true, "auth.uid()"], ["planning_metas_compra", "created_at", "timestamp with time zone", true, "now()"], ["planning_metas_compra", "updated_at", "timestamp with time zone", true, "now()"], ["planning_metas_compra", "company_id", "uuid", true, "get_current_company_id()"], ["rh_custos_mensais", "id", "uuid", true, "gen_random_uuid()"], ["rh_custos_mensais", "periodo", "text", true, null], ["rh_custos_mensais", "total_salarios", "numeric", true, "0"], ["rh_custos_mensais", "total_horas_extras", "numeric", true, "0"], ["rh_custos_mensais", "total_beneficios", "numeric", true, "0"], ["rh_custos_mensais", "total_encargos", "numeric", true, "0"], ["rh_custos_mensais", "total_insalubridade", "numeric", true, "0"], ["rh_custos_mensais", "total_noturno", "numeric", true, "0"], ["rh_custos_mensais", "total_geral", "numeric", true, "0"], ["rh_custos_mensais", "qtd_colaboradores", "integer", true, "0"], ["rh_custos_mensais", "custo_medio_colaborador", "numeric", true, "0"], ["rh_custos_mensais", "detalhamento", "jsonb", false, "'[]'::jsonb"], ["rh_custos_mensais", "calculado_por", "uuid", false, null], ["rh_custos_mensais", "calculado_em", "timestamp with time zone", true, "now()"], ["rh_custos_mensais", "observacoes", "text", false, "''::text"], ["rh_custos_mensais", "created_at", "timestamp with time zone", true, "now()"], ["rh_custos_mensais", "updated_at", "timestamp with time zone", true, "now()"], ["rh_custos_mensais", "company_id", "uuid", true, "get_current_company_id()"], ["rh_escalas", "id", "uuid", true, "gen_random_uuid()"], ["rh_escalas", "semana_inicio", "date", true, null], ["rh_escalas", "setor", "text", true, "'salao'::text"], ["rh_escalas", "status", "text", true, "'RASCUNHO'::text"], ["rh_escalas", "publicada_em", "timestamp with time zone", false, null], ["rh_escalas", "publicada_por", "uuid", false, null], ["rh_escalas", "custo_projetado", "numeric", false, "0"], ["rh_escalas", "observacoes", "text", false, "''::text"], ["rh_escalas", "created_at", "timestamp with time zone", true, "now()"], ["rh_escalas", "updated_at", "timestamp with time zone", true, "now()"], ["rh_escalas", "created_by", "uuid", false, null], ["rh_escalas", "company_id", "uuid", true, "get_current_company_id()"]]$expected$::jsonb THEN RAISE EXCEPTION 'PHASE7_UPSERT_COLUMNS_DRIFT'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.planning_metas_compra WHERE company_id IS NULL) OR EXISTS(SELECT 1 FROM public.planning_metas_compra GROUP BY company_id,year,month,categoria HAVING count(*)>1) THEN RAISE EXCEPTION 'PHASE7_UPSERT_INTEGRITY_REQUIRED: planning_metas_compra'; END IF; END $$;
ALTER TABLE public.planning_metas_compra ADD CONSTRAINT phase7_planning_metas_compra_tenant_key UNIQUE(company_id,year,month,categoria);
ALTER TABLE public.planning_metas_compra DROP CONSTRAINT planning_metas_compra_year_month_categoria_key;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.rh_custos_mensais WHERE company_id IS NULL) OR EXISTS(SELECT 1 FROM public.rh_custos_mensais GROUP BY company_id,periodo HAVING count(*)>1) THEN RAISE EXCEPTION 'PHASE7_UPSERT_INTEGRITY_REQUIRED: rh_custos_mensais'; END IF; END $$;
ALTER TABLE public.rh_custos_mensais ADD CONSTRAINT phase7_rh_custos_mensais_tenant_key UNIQUE(company_id,periodo);
ALTER TABLE public.rh_custos_mensais DROP CONSTRAINT rh_custos_mensais_periodo_key;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.rh_escalas WHERE company_id IS NULL) OR EXISTS(SELECT 1 FROM public.rh_escalas GROUP BY company_id,semana_inicio,setor HAVING count(*)>1) THEN RAISE EXCEPTION 'PHASE7_UPSERT_INTEGRITY_REQUIRED: rh_escalas'; END IF; END $$;
ALTER TABLE public.rh_escalas ADD CONSTRAINT phase7_rh_escalas_tenant_key UNIQUE(company_id,semana_inicio,setor);
ALTER TABLE public.rh_escalas DROP CONSTRAINT rh_escalas_semana_inicio_setor_key;
NOTIFY pgrst, 'reload schema';
COMMIT;
